 def read():return {k:app.data.request('GET','/api/'+v)for k,v in [('story','story'),('master','concept'),('npcs','npcs')]}
 sources=read();validate(plan,sources);spec=plan['requests'][0];correction=spec['kind']=='ui-mockup-correction'
 if value['requestKey']!=spec['key']:raise ValueError('MOCKUP_REQUEST_KEY')
